package io.knowledgebrain.brainquery;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BrainProjectionTest {
 static UUID id(){return BrainProjectionIntegrationTest.id();}
 static byte[] concept(UUID space,UUID id,long version,String state){var p=io.knowledgebrain.contracts.knowledge.v1.ConceptChangedPayloadV1.newBuilder().setConceptId(id.toString()).setRevisionId(id().toString()).setVersion(version).setState(state).setVisibility("PRIVATE").setTitle("Title").setDescription("Description").build();return io.knowledgebrain.contracts.knowledge.v1.EventEnvelopeV1.newBuilder().setEventId(id().toString()).setProducer("knowledge-service").setAggregateType("Concept").setAggregateId(id.toString()).setSpaceId(space.toString()).setActorId(id().toString()).setOccurredAtEpochMillis(1).setTraceId("a".repeat(32)).setEventVersion(1).setEventType(state.equals("RETIRED")?"ConceptRetired":version==1?"ConceptCreated":"ConceptUpdated").setPayload(p.toByteString()).build().toByteArray();}
 @Test void existingConceptContractValidatesTransportAndHidesRetiredText()throws Exception{var space=id();var id=id();byte[] wire=concept(space,id,2,"ACTIVE");var e=io.knowledgebrain.contracts.knowledge.v1.EventEnvelopeV1.parseFrom(wire);var headers=Map.of("id",e.getEventId(),"schema_group","knowledge","schema_artifact","concept-events","schema_version","1","trace_id",e.getTraceId());assertEquals("Title",BrainProjection.decode("knowledge.concept.v1",wire,id.toString(),headers).title());assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("knowledge.concept.v1",wire,id().toString(),headers));assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("knowledge.concept.v1",wire,id.toString(),Map.of()));assertEquals("",BrainProjection.decode("knowledge.concept.v1",concept(space,id,3,"RETIRED")).title());assertThrows(IllegalArgumentException.class,()->BrainProjection.decode("knowledge.concept.v1",concept(space,id,0,"ACTIVE")));}
 @Test void noteConceptsUsePublishedAggregateAndArtifactWithIndependentVersion(){var p=io.knowledgebrain.contracts.content.concepts.v1.NoteConceptsChangedPayloadV1.newBuilder().setNoteId(id().toString()).setRevisionId(id().toString()).setConceptVersion(7).setNoteVersion(2).setNoteState("ACTIVE").addLinks(io.knowledgebrain.contracts.content.concepts.v1.NoteConceptLinkV1.newBuilder().setLinkId(id().toString()).setConceptId(id().toString())).build();var e=io.knowledgebrain.contracts.content.concepts.v1.ConceptEventEnvelopeV1.newBuilder().setEventId(id().toString()).setProducer("content-service").setAggregateType("NoteConceptLinks").setAggregateId(p.getNoteId()).setSpaceId(id().toString()).setActorId(id().toString()).setOccurredAtEpochMillis(1).setTraceId("a".repeat(32)).setEventVersion(1).setEventType("NoteConceptsChanged").setPayload(p.toByteString()).build();var h=Map.of("id",e.getEventId(),"schema_group","content","schema_artifact","note-concepts-events","schema_version","1","trace_id",e.getTraceId());assertEquals(7,BrainProjection.decode("content.note-concepts.v1",e.toByteArray(),p.getNoteId(),h).version());}
 @Test void fixedSearchQueryRejectsDslTypesPaginationAndControlCharacters(){assertNotNull(NoteSearchClient.brainQuery(id(),"Java",0,20,null));for(String kind:List.of("SOURCE","note","*"))assertThrows(IllegalArgumentException.class,()->NoteSearchClient.brainQuery(id(),"Java",0,20,kind));assertThrows(IllegalArgumentException.class,()->NoteSearchClient.brainQuery(id(),"x\n",0,20,null));assertThrows(IllegalArgumentException.class,()->NoteSearchClient.brainQuery(id(),"x",1000,20,null));}
}
